struct tile
{
    SDL_Rect tileRect;
    int isActive;
    int selectedTile;
};

struct map
{
    SDL_Renderer *pRenderer;
    SDL_Texture *pTexture;
    SDL_Rect rect;
    Tile tileMap[AMOUNT_OF_TILES_HORIZONTAL][AMOUNT_OF_TILES_VERTICAL];
};

Map *createMap(SDL_Renderer *pRenderer, int window_width, int window_height)
{
    Map *map = malloc(sizeof(Map));
    if(!map) return NULL;

    map->pRenderer = pRenderer;

    SDL_Surface *surface = IMG_Load("Resources/Sprite-all.png");
    if (!surface) {
        printf("Error loading spritesheet: %s\n", IMG_GetError());
        free(map);
        return NULL;
    }

    map->pTexture = SDL_CreateTextureFromSurface(pRenderer, surface);
    SDL_FreeSurface(surface);

    if (!map->pTexture) {
        printf("Error creating tile texture: %s\n", SDL_GetError());
        free(map);
        return NULL;
    }

    for (int x = 0; x < AMOUNT_OF_TILES_HORIZONTAL; x++) 
    {
        for (int y = 0; y < AMOUNT_OF_TILES_VERTICAL; y++) 
        {
            map->tileMap[x][y] = createTile(x*TILESIZE_PIXELS, y*TILESIZE_PIXELS, mapTemplate1[x][y]);
        }
    }
    return map;
}

Map *createServerMap(int window_width, int window_height)
{
    Map *map = malloc(sizeof(Map));
    if(!map) return NULL;

    map->pRenderer = NULL;
    map->pTexture = NULL;

    for (int x = 0; x < AMOUNT_OF_TILES_HORIZONTAL; x++) 
    {
        for (int y = 0; y < AMOUNT_OF_TILES_VERTICAL; y++) 
        {
            map->tileMap[x][y] = createTile(x*TILESIZE_PIXELS, y*TILESIZE_PIXELS, mapTemplate1[x][y]);
        }
    }
    return map;
}

void drawTiles(Map *tiles)
{
    for (int x = 0; x < AMOUNT_OF_TILES_HORIZONTAL; x++)
    {
        for(int y = 0; y < AMOUNT_OF_TILES_VERTICAL; y++)
        {
            SDL_Rect selectedTexture = getSelectedTextureTile(tiles->tileMap[x][y].selectedTile);
            if (!tiles->tileMap[x][y].isActive) continue;
            SDL_RenderCopy(tiles->pRenderer, tiles->pTexture, &selectedTexture, &tiles->tileMap[x][y].tileRect);
        }
    }
}

SDL_Rect getSelectedTextureTile(int tileNr)
{
    SDL_Rect selectedTexture;
    selectedTexture.x = (tileNr % 3)*64;
    selectedTexture.y = (tileNr / 3)*64;
    selectedTexture.w = 64;
    selectedTexture.h = 64;
    return selectedTexture;
}

void setSelectedTexture(Map *tiles, int x, int y, int selectedTexture)
{
    tiles->tileMap[x][y].selectedTile = selectedTexture;
}

int getSelectedTexture(Map *tiles, int x, int y)
{
    return tiles->tileMap[x][y].selectedTile;
}

SDL_Rect getTileRect(Map *tiles, int x, int y)
{
    return tiles->tileMap[x][y].tileRect;
}

int isTileActive(Map *tiles, int x, int y)
{
    return tiles->tileMap[x][y].isActive;
}

void inactivateTile(Map *tiles, int x, int y)
{
    tiles->tileMap[x][y].isActive = 0;
}

void destroyTiles(Map *tiles)
{
    if (!tiles) return;
    if (tiles->pTexture) SDL_DestroyTexture(tiles->pTexture);
    free(tiles);
}


Tile createTile(int x, int y, int selectedTile)
{
    Tile tile;

    tile.tileRect.x = x;
    tile.tileRect.y = y;
    tile.tileRect.h = TILESIZE_PIXELS;
    tile.tileRect.w = TILESIZE_PIXELS;
    tile.selectedTile = selectedTile;
    if (selectedTile == -1)
    {
        tile.isActive = 0;
    }
    else tile.isActive = 1;
    return tile;
}